fn solve(s: Vec<char>) -> Vec<char> {
    let mut buffer = Vec::new();
    for &c in &s {
        match c {
            '0' | '1' => buffer.push(c),
            'B'       => { buffer.pop(); },
            _         => {}  // impossible by problem statement
        }
    }
    buffer
}

